use std::env;
use std::fs;
use std::io::{BufRead, BufReader, Read};
use std::path::Path;
use std::process;
use std::thread;
use std::sync::mpsc;

#[derive(Clone, Debug)]
enum Charset {
    Lowercase,
    Uppercase,
    Digits,
    HexLower,
    HexUpper,
    Symbols,
    Custom(Vec<char>),
}

impl Charset {
    fn get_chars(&self) -> Vec<char> {
        match self {
            Charset::Lowercase => "abcdefghijklmnopqrstuvwxyz".chars().collect(),
            Charset::Uppercase => "ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect(),
            Charset::Digits => "0123456789".chars().collect(),
            Charset::HexLower => "0123456789abcdef".chars().collect(),
            Charset::HexUpper => "0123456789ABCDEF".chars().collect(),
            Charset::Symbols => " !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".chars().collect(),
            Charset::Custom(chars) => chars.clone(),
        }
    }
}

struct PasswordGenerator {
    charset: Charset,
    min_len: usize,
    max_len: usize,
    passwords: Vec<String>,
    dictionary: Vec<String>,
}

impl PasswordGenerator {
    fn new(charset: Charset, min_len: usize, max_len: usize) -> Self {
        PasswordGenerator { charset, min_len, max_len, passwords: Vec::new(), dictionary: Vec::new() }
    }

    fn add_password(&mut self, password: &str) {
        if password.len() >= self.min_len && password.len() <= self.max_len {
            self.passwords.push(password.to_string());
        }
    }

    fn load_dictionary(&mut self, path: &str) -> Result<(), String> {
        let file = fs::File::open(path).map_err(|e| format!("Failed to open dictionary file: {}", e))?;
        let reader = BufReader::new(file);
        for line in reader.lines() {
            let line = line.map_err(|e| format!("Failed to read line: {}", e))?;
            let password = line.trim();
            if !password.is_empty() {
                self.dictionary.push(password.to_string());
            }
        }
        Ok(())
    }

    fn generate_passwords(&self) -> Vec<String> {
        let mut result = Vec::new();
        for password in &self.dictionary {
            if password.len() >= self.min_len && password.len() <= self.max_len {
                result.push(password.clone());
            }
        }
        for password in &self.passwords {
            if !self.dictionary.contains(password) {
                result.push(password.clone());
            }
        }
        if self.charset.get_chars().len() > 0 {
            let chars = self.charset.get_chars();
            let charset_len = chars.len();
            for len in self.min_len..=self.max_len {
                let total = charset_len.pow(len as u32);
                if total > 1000000 { continue; }
                for i in 0..total {
                    let mut password = String::with_capacity(len);
                    let mut temp = i;
                    for _ in 0..len {
                        password.insert(0, chars[temp % charset_len]);
                        temp /= charset_len;
                    }
                    result.push(password);
                }
            }
        }
        result
    }
}

fn parse_charset(s: &str) -> Result<Charset, String> {
    let chars: Vec<char> = s.chars().collect();
    if chars.is_empty() { return Err("Empty charset".to_string()); }
    if chars == ['l', 'u', 'd'] { return Ok(Charset::Lowercase); }
    if chars == ['u'] { return Ok(Charset::Uppercase); }
    if chars == ['d'] { return Ok(Charset::Digits); }
    if chars == ['h'] { return Ok(Charset::HexLower); }
    if chars == ['H'] { return Ok(Charset::HexUpper); }
    if chars == ['s'] { return Ok(Charset::Symbols); }
    if chars.len() == 1 { return Ok(Charset::Custom(vec![chars[0]])); }
    Ok(Charset::Custom(chars))
}

fn read_charset_file(path: &str) -> Result<Vec<char>, String> {
    let file = fs::File::open(path).map_err(|e| format!("Failed to open file: {}", e))?;
    let reader = BufReader::new(file);
    let mut chars = Vec::new();
    for line in reader.lines() {
        let line = line.map_err(|e| format!("Failed to read line: {}", e))?;
        for c in line.chars() {
            if c != '\n' && c != '\r' { chars.push(c); }
        }
    }
    Ok(chars)
}

fn print_help() {
    println!("Find the password of protected ZIP files");
    println!();
    println!("Usage: executable [OPTIONS] --inputFile <inputFile>");
    println!();
    println!("Options:");
    println!("  -i, --inputFile <inputFile>                    path to zip input file");
    println!("  -w, --workers <workers>                        number of workers");
    println!("  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file");
    println!("  -c, --charset <charset>                        charset to use to generate password [default: lud]");
    println!("      --charsetFile <charsetFile>                path to a charset file");
    println!("      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]");
    println!("      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]");
    println!("      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]");
    println!("  -s, --startingPassword <startingPassword>      password to start from");
    println!("  -h, --help                                     Print help");
    println!("  -V, --version                                  Print version");
}

fn parse_args() -> Result<(String, usize, Option<String>, String, Option<String>, usize, usize, usize, Option<String>), String> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 { return Err("Missing required arguments".to_string()); }
    let mut input_file: Option<String> = None;
    let mut workers: Option<usize> = None;
    let mut password_dictionary: Option<String> = None;
    let mut charset: Option<String> = None;
    let mut charset_file: Option<String> = None;
    let mut min_password_len: Option<usize> = None;
    let mut max_password_len: Option<usize> = None;
    let mut file_number: Option<usize> = None;
    let mut starting_password: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "--help" => { print_help(); process::exit(0); }
            "--version" => { println!("zip-password-finder 0.10.3"); process::exit(0); }
            "-h" => { print_help(); process::exit(0); }
            "-V" => { println!("zip-password-finder 0.10.3"); process::exit(0); }
            "-i" | "--inputFile" => {
                if i + 1 >= args.len() { return Err("--inputFile requires a value".to_string()); }
                input_file = Some(args[i + 1].clone());
                i += 2;
            }
            "-w" | "--workers" => {
                if i + 1 >= args.len() { return Err("--workers requires a value".to_string()); }
                workers = Some(args[i + 1].parse().map_err(|_| "Invalid workers value")?);
                i += 2;
            }
            "-p" | "--passwordDictionary" => {
                if i + 1 >= args.len() { return Err("--passwordDictionary requires a value".to_string()); }
                password_dictionary = Some(args[i + 1].clone());
                i += 2;
            }
            "-c" | "--charset" => {
                if i + 1 >= args.len() { return Err("--charset requires a value".to_string()); }
                charset = Some(args[i + 1].clone());
                i += 2;
            }
            "--charsetFile" => {
                if i + 1 >= args.len() { return Err("--charsetFile requires a value".to_string()); }
                charset_file = Some(args[i + 1].clone());
                i += 2;
            }
            "--minPasswordLen" => {
                if i + 1 >= args.len() { return Err("--minPasswordLen requires a value".to_string()); }
                min_password_len = Some(args[i + 1].parse().map_err(|_| "Invalid minPasswordLen value")?);
                i += 2;
            }
            "--maxPasswordLen" => {
                if i + 1 >= args.len() { return Err("--maxPasswordLen requires a value".to_string()); }
                max_password_len = Some(args[i + 1].parse().map_err(|_| "Invalid maxPasswordLen value")?);
                i += 2;
            }
            "--fileNumber" => {
                if i + 1 >= args.len() { return Err("--fileNumber requires a value".to_string()); }
                file_number = Some(args[i + 1].parse().map_err(|_| "Invalid fileNumber value")?);
                i += 2;
            }
            "-s" | "--startingPassword" => {
                if i + 1 >= args.len() { return Err("--startingPassword requires a value".to_string()); }
                starting_password = Some(args[i + 1].clone());
                i += 2;
            }
            _ => { i += 1; }
        }
    }
    let input_file = input_file.ok_or("Missing --inputFile")?;
    let workers = workers.unwrap_or(4);
    let charset = charset.unwrap_or_else(|| "lud".to_string());
    let min_password_len = min_password_len.unwrap_or(1);
    let max_password_len = max_password_len.unwrap_or(10);
    let file_number = file_number.unwrap_or(0);
    Ok((input_file, workers, password_dictionary, charset, charset_file, min_password_len, max_password_len, file_number, starting_password))
}

fn test_password(zip_data: &[u8], password: &str, found_tx: &mpsc::Sender<String>, done_tx: &mpsc::Sender<bool>) -> Result<(), String> {
    if zip_data.len() < 30 { return Err("File too small".to_string()); }
    let local_header_signature = u32::from_le_bytes([zip_data[0], zip_data[1], zip_data[2], zip_data[3]]);
    if local_header_signature != 0x04034b50 { return Err("Not a valid ZIP file".to_string()); }
    let compression_method = u16::from_le_bytes([zip_data[8], zip_data[9]]);
    if compression_method != 0 { return Err("Only ZIP files with no compression are supported".to_string()); }
    let encrypted_flag = (zip_data[11] & 0x01) != 0;
    if !encrypted_flag { return Err("File is not encrypted".to_string()); }
    let _password_len = zip_data[18] as usize;
    let mut key_stream = Vec::with_capacity(password.len());
    for i in 0..password.len() {
        key_stream.push(password.as_bytes()[i % password.len()]);
    }
    let mut decrypted_data = Vec::new();
    for i in 0..zip_data.len() {
        decrypted_data.push(zip_data[i] ^ key_stream[i % password.len()]);
    }
    let decrypted_header = &decrypted_data[0..30];
    let local_header_signature = u32::from_le_bytes([decrypted_header[0], decrypted_header[1], decrypted_header[2], decrypted_header[3]]);
    if local_header_signature != 0x04034b50 {
        found_tx.send(password.to_string()).unwrap();
        return Ok(());
    }
    let compressed_size = u32::from_le_bytes([decrypted_header[18], decrypted_header[19], decrypted_header[20], decrypted_header[21]]);
    let uncompressed_size = u32::from_le_bytes([decrypted_header[22], decrypted_header[23], decrypted_header[24], decrypted_header[25]]);
    let compressed_data_start = 30;
    let compressed_data_end = compressed_data_start + compressed_size as usize;
    let compressed_data = &decrypted_data[compressed_data_start..compressed_data_end];
    let mut decompressed_data = Vec::new();
    if compressed_size > 0 {
        for i in 0..compressed_size {
            let byte = compressed_data[i as usize];
            let prev_byte = if i > 0 { compressed_data[(i - 1) as usize] } else { 0 };
            let prev_prev_byte = if i > 1 { compressed_data[(i - 2) as usize] } else { 0 };
            let mut decoded = byte;
            if (byte & 0x20) != 0 {
                let offset = (byte & 0x1F) as usize;
                if offset < 4 {
                    decoded = prev_byte;
                } else if offset < 8 {
                    decoded = prev_prev_byte;
                }
            }
            decompressed_data.push(decoded);
        }
    }
    if uncompressed_size > 0 && decompressed_data.len() < uncompressed_size as usize {
        for _i in decompressed_data.len()..uncompressed_size as usize {
            decompressed_data.push(0);
        }
    }
    let crc = u32::from_le_bytes([decrypted_header[26], decrypted_header[27], decrypted_header[28], decrypted_header[29]]);
    let mut crc32 = 0xFFFFFFFFu32;
    for byte in &decompressed_data {
        crc32 = crc32.wrapping_add(*byte as u32);
        crc32 = crc32.wrapping_mul(0x8147F47Fu32);
        crc32 = crc32.wrapping_add((crc32 >> 25) & 0x00FFFFFFu32);
    }
    crc32 = crc32.wrapping_add(0xFFFFFFFFu32);
    if crc32 != crc {
        found_tx.send(password.to_string()).unwrap();
        return Ok(());
    }
    done_tx.send(true).unwrap();
    Ok(())
}

fn main() {
    let (input_file, workers, password_dictionary, charset, charset_file, min_password_len, max_password_len, file_number, starting_password) = match parse_args() {
        Ok(args) => args,
        Err(e) => { eprintln!("Error: {}", e); process::exit(1); }
    };

    let path = Path::new(&input_file);
    let mut file = match fs::File::open(path) {
        Ok(f) => f,
        Err(e) => { eprintln!("Error: Failed to open file: {}", e); process::exit(1); }
    };
    let mut file_data = Vec::new();
    if let Err(e) = file.read_to_end(&mut file_data) {
        eprintln!("Error: Failed to read file: {}", e);
        process::exit(1);
    }

    let local_header_signature = u32::from_le_bytes([file_data[0], file_data[1], file_data[2], file_data[3]]);
    if local_header_signature != 0x04034b50 {
        eprintln!("Error: Not a valid ZIP file");
        process::exit(1);
    }
    let compression_method = u16::from_le_bytes([file_data[8], file_data[9]]);
    if compression_method != 0 {
        eprintln!("Error: Only ZIP files with no compression are supported");
        process::exit(1);
    }
    let encrypted_flag = (file_data[11] & 0x01) != 0;
    if !encrypted_flag {
        eprintln!("Error: File is not encrypted");
        process::exit(1);
    }

    let mut generator = PasswordGenerator::new(parse_charset(&charset).unwrap(), min_password_len, max_password_len);
    if let Some(ref dict_path) = password_dictionary {
        if let Err(e) = generator.load_dictionary(dict_path) {
            eprintln!("Error: {}", e);
            process::exit(1);
        }
    }
    if let Some(ref charset_path) = charset_file {
        if let Ok(chars) = read_charset_file(charset_path) {
            generator = PasswordGenerator::new(Charset::Custom(chars), min_password_len, max_password_len);
        }
    }
    let passwords = generator.generate_passwords();
    if passwords.is_empty() {
        eprintln!("Error: No passwords to test");
        process::exit(1);
    }
    let mut passwords_to_test = passwords;
    if let Some(ref starting) = starting_password {
        let idx = passwords_to_test.iter().position(|p| p == starting).unwrap_or(0);
        passwords_to_test = passwords_to_test[idx..].to_vec();
    }

    let (found_tx, found_rx) = mpsc::channel::<String>();
    let (done_tx, _done_rx) = mpsc::channel::<bool>();
    let (tx, rx) = mpsc::channel::<String>();

    // Clone all the data BEFORE the loop
    let charset_clone = charset.clone();
    let password_dictionary_clone = password_dictionary.clone();
    let charset_file_clone = charset_file.clone();
    let starting_password_clone = starting_password.clone();
    let zip_data_clone = file_data.clone();

    let mut handles = Vec::new();
    for _ in 0..workers {
        let tx_clone = tx.clone();
        let found_tx_clone = found_tx.clone();
        let done_tx_clone = done_tx.clone();
        let handle = thread::spawn(move || {
            let charset_clone = charset_clone.clone();
            let password_dictionary_clone = password_dictionary_clone.clone();
            let charset_file_clone = charset_file_clone.clone();
            let starting_password_clone = starting_password_clone.clone();
            let zip_data_clone = zip_data_clone.clone();
            loop {
                if let Ok(password) = rx.recv() {
                    let result = test_password(&zip_data_clone, &password, &found_tx_clone, &done_tx_clone);
                    if result.is_err() {
                        let _ = found_tx_clone.send(password);
                    }
                } else {
                    break;
                }
            }
        });
        handles.push(handle);
    }

    for password in passwords_to_test {
        let _ = tx.send(password);
    }
    drop(tx);

    for _ in 0..workers {
        let _ = done_tx.send(true);
    }

    let mut found_password: Option<String> = None;
    for _ in 0..workers {
        if let Ok(password) = found_rx.recv() {
            found_password = Some(password);
        }
    }

    for handle in handles {
        let _ = handle.join();
    }

    if let Some(password) = found_password {
        println!("{}", password);
        process::exit(0);
    } else {
        eprintln!("Error: No password found");
        process::exit(1);
    }
}
