fn test_password(zip_data: &[u8], password: &str, found_tx: &mpsc::Sender<String>, done_tx: &mpsc::Sender<bool>) -> Result<(), String> {
    if zip_data.len() < 30 { return Err("File too small".to_string()); }
    let local_header_signature = u32::from_le_bytes([zip_data[0], zip_data[1], zip_data[2], zip_data[3]]);
    if local_header_signature != 0x04034b50 { return Err("Not a valid ZIP file".to_string()); }
    let compression_method = u16::from_le_bytes([zip_data[8], zip_data[9]]);
    if compression_method != 0 { return Err("Only ZIP files with no compression are supported".to_string()); }
    let encrypted_flag = (zip_data[11] & 0x01) != 0;
    if !encrypted_flag { return Err("File is not encrypted".to_string()); }
    let _password_len = zip_data[18] as usize;
    let mut key_stream = Vec::with_capacity(password.len());
    for i in 0..password.len() {
        key_stream.push(password.as_bytes()[i % password.len()]);
    }
    let mut decrypted_data = Vec::new();
    for i in 0..zip_data.len() {
        decrypted_data.push(zip_data[i] ^ key_stream[i % password.len()]);
    }
    let decrypted_header = &decrypted_data[0..30];
    let local_header_signature = u32::from_le_bytes([decrypted_header[0], decrypted_header[1], decrypted_header[2], decrypted_header[3]]);
    if local_header_signature != 0x04034b50 {
        found_tx.send(password.to_string()).unwrap();
        return Ok(());
    }
    let compressed_size = u32::from_le_bytes([decrypted_header[18], decrypted_header[19], decrypted_header[20], decrypted_header[21]]);
    let uncompressed_size = u32::from_le_bytes([decrypted_header[22], decrypted_header[23], decrypted_header[24], decrypted_header[25]]);
    let compressed_data_start = 30;
    let compressed_data_end = compressed_data_start + compressed_size as usize;
    let compressed_data = &decrypted_data[compressed_data_start..compressed_data_end];
    let mut decompressed_data = Vec::new();
    if compressed_size > 0 {
        for i in 0..compressed_size {
            let byte = compressed_data[i as usize];
            let prev_byte = if i > 0 { compressed_data[(i - 1) as usize] } else { 0 };
            let prev_prev_byte = if i > 1 { compressed_data[(i - 2) as usize] } else { 0 };
            let mut decoded = byte;
            if (byte & 0x20) != 0 {
                let offset = (byte & 0x1F) as usize;
                if offset < 4 {
                    decoded = prev_byte;
                } else if offset < 8 {
                    decoded = prev_prev_byte;
                }
            }
            decompressed_data.push(decoded);
        }
    }
    if uncompressed_size > 0 && decompressed_data.len() < uncompressed_size as usize {
        for _i in decompressed_data.len()..uncompressed_size as usize {
            decompressed_data.push(0);
        }
    }
    let crc = u32::from_le_bytes([decrypted_header[26], decrypted_header[27], decrypted_header[28], decrypted_header[29]]);
    let mut crc32 = 0xFFFFFFFFu32;
    for byte in &decompressed_data {
        crc32 = crc32.wrapping_add(*byte as u32);
        crc32 = crc32.wrapping_mul(0x8147F47Fu32);
        crc32 = crc32.wrapping_add((crc32 >> 25) & 0x00FFFFFFu32);
    }
    crc32 = crc32.wrapping_add(0xFFFFFFFFu32);
    if crc32 != crc {
        found_tx.send(password.to_string()).unwrap();
        return Ok(());
    }
    done_tx.send(true).unwrap();
    Ok(())
}

fn main() {
